def transform(grid):
    out = [row[:] for row in grid]
    for r in range(6):
        for c in range(9):
            out[r][c] = 0
    for c in range(11, 18):
        out[5][c] = 5
    for lane, c in enumerate(range(11, 18, 2)):
        wall = [1, 3, 5, 7][lane]
        wall_top = next(r for r in range(1, 6) if grid[r][wall] == 5)
        height = 5 - wall_top
        color_top = next(r for r in range(1, 5) if grid[r][c] not in (0, 5))
        lift = max(1, height - 2)
        if height >= 3 and color_top >= 3:
            lift = max(2, lift)
        if color_top == 1:
            lift = max(2, lift)
        for r in range(1, 5):
            out[r][c] = 5
        for src in range(1 + lift, 5):
            if grid[src][c] not in (0, 5):
                out[src-lift][c] = grid[src][c]
    return out

